def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        safe_bid = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 2:
            safe_bid = DAILY_SALARY * 0.75
        return float(min(budget, safe_bid))

    prev_bids = []
    high_threat = 0
    cindy_alive = False
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 85:
                high_threat += 1
        if opp.get('daily_salary') == 70 and opp.get('water_requirement') == 13 and opp.get('budget', 0) > 500:
            prev2 = opp.get('previous_trace', {})
            if prev2.get('bid') is not None and prev2.get('bid') >= 80:
                cindy_alive = True

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days == 1:
        urgency += 1

    abundance = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if abundance >= 0.8:
        urgency += 1

    if urgency >= 5:
        bid = max(88.0, highest_prev + 1.0)
    elif urgency >= 3:
        if supply >= 22:
            bid = max(72.0, avg_prev + 1.5)
        else:
            bid = max(78.0, highest_prev * 0.98)
    else:
        if cindy_alive and supply <= 18:
            bid = 8.0
        elif supply >= 23:
            bid = 61.0
        elif supply >= 20:
            bid = 36.0
        else:
            bid = 12.0

    if day >= 8 and hp > 5 and no_water_days == 0 and budget < 120:
        bid = min(bid, 25.0)

    if budget < 40:
        if urgency >= 4:
            bid = budget
        else:
            bid = min(bid, max(0.0, budget * 0.45))

    bid = max(0.0, min(float(budget), float(bid)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4)

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    # Pressure estimate: if someone previously bid very high, expect continued contest
    high_pressure = highest_prev_bid >= 0.85 * DAILY_SALARY

    # Supply-based aggressiveness: when supply is high, the marginal value of winning is lower.
    # We'll bid just enough to beat likely mid/high bids without burning budget.
    if supply >= 0.9 * MAX_SUPPLY:
        base = 0.55 * DAILY_SALARY
    elif supply <= 1.1 * MIN_SUPPLY:
        base = 0.65 * DAILY_SALARY
    else:
        base = 0.60 * DAILY_SALARY

    # If we're in danger (low hp or many no-water days), increase bid.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        base = 0.85 * DAILY_SALARY
    elif my_hp <= 4.0:
        base = max(base, 0.70 * DAILY_SALARY)

    # If Cindy-like behavior suggests high contest (high_pressure), slightly raise; otherwise keep conservative.
    if high_pressure:
        base = max(base, 0.75 * DAILY_SALARY)
    else:
        base = min(base, 0.70 * DAILY_SALARY)

    # Ensure we don't exceed budget; also cap to avoid irrational overpay.
    bid = min(my_budget, base)

    # Small adaptive bump to outbid typical mid bids when we have enough budget.
    if my_budget > 0 and bid < 0.75 * DAILY_SALARY and supply >= 18.0:
        bid = min(my_budget, bid + 5.0)

    # Final safety clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    # Determine alive opponents
    alive_opponents = {oid: o for oid, o in opponents_status.items() if o['alive']}
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Collect yesterday's bids from opponent traces
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            yesterday_bids.append(prev['bid'])

    # Estimate bid based on yesterday's max and opponent hp
    max_last_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Own hp threshold
    if my_status['hp'] <= 2:
        # Must get water at almost any cost
        target_bid = min(my_status['budget'], max(DAILY_SALARY * 0.9, max_last_bid + 5.0))
    else:
        # Can be more conservative
        target_bid = min(my_status['budget'], max(DAILY_SALARY * 0.6, max_last_bid + 2.0))

    # Ensure we don't waste budget when supply is low: if supply is too low for all, might need higher bid
    supply = day_context['supply']
    # But we just keep simple
    return target_bid
